import os, sys, math
sys.path.insert(0, os.path.join(os.path.dirname(__file__), '..', 'author'))
from _lib import *
G = Gen('m05', 14, 20250505, dict(ia=('Instrumentation amplifiers', 'Mạch khuếch đại thiết bị'), iso=('Isolation amplifiers', 'Mạch khuếch đại cách ly'), ota=('OTA', 'Mạch khuếch đại hỗ dẫn (OTA)'), log=('Log and antilog amplifiers', 'Mạch logarit và đối logarit')))
g, fmt, add = G.g, G.fmt, G.add; S = lambda a, b: (a, b)
for rg in [1.0, 0.51, 2.2, 5.1, 10, 0.2, 4.7, 0.1]:
    a = 1 + 50.5 / rg
    add('ia', f'An AD622 instrumentation amplifier has RG = {rg} kΩ. What is its voltage gain? (G = 1 + 50.5 kΩ/RG)', f'AD622 có RG = {rg} kΩ. Độ lợi điện áp là bao nhiêu? (G = 1 + 50,5 kΩ/RG)', g(a, 4), [g(50.5 / rg, 4), g(1 + rg / 50.5, 4), g(a * 2, 4), g(1 + 100 / rg, 4)], f'G = 1 + 50.5/{rg} = {g(a,4)} (the “1 +” is part of the formula).', f'G = 1 + 50,5/{rg} = {g(a,4)} (số “1 +” là một phần của công thức).', S('Floyd Problem 5', 'Floyd Bài 5'))
for gn in [10, 20, 50, 100, 200, 1000]:
    rg = 50.5e3 / (gn - 1)
    add('ia', f'What RG must an AD622 use for a gain of {gn}? (G = 1 + 50.5 kΩ/RG)', f'AD622 cần RG bằng bao nhiêu để có độ lợi {gn}? (G = 1 + 50,5 kΩ/RG)', fmt(rg, 'Ω'), [fmt(50.5e3 / gn, 'Ω'), fmt(50.5e3 * (gn - 1), 'Ω'), fmt(rg / 10, 'Ω'), fmt(rg * 10, 'Ω')], f'RG = 50.5 kΩ/(G − 1) = 50.5 kΩ/{gn-1} = {g(rg)} Ω.', f'RG = 50,5 kΩ/(G − 1) = 50,5 kΩ/{gn-1} = {g(rg)} Ω.', S('Floyd Problem 7', 'Floyd Bài 7'), 2)
for r, rg in [(100, 1.0), (50, 1.0), (47, 2.2), (100, 0.5), (22, 1.0), (68, 4.7)]:
    a = 1 + 2 * r / rg
    add('ia', f'A three-op-amp instrumentation amplifier has R1 = R2 = {r} kΩ, RG = {rg} kΩ and a unity-gain difference stage. What is the overall gain?', f'Mạch khuếch đại thiết bị ba op-amp có R1 = R2 = {r} kΩ, RG = {rg} kΩ và tầng hiệu có độ lợi 1. Độ lợi tổng là bao nhiêu?', g(a, 4), [g(1 + r / rg, 4), g(2 * r / rg, 4), g(r / rg, 4), g((1 + r / rg) ** 2, 4)], f'Av = 1 + 2R/RG = 1 + {2*r}/{rg} = {g(a,4)}.', f'Av = 1 + 2R/RG = 1 + {2*r}/{rg} = {g(a,4)}.', S('Floyd Problem 2', 'Floyd Bài 2'), 2)
for gain, v1, v2, vcm in [(201, 5, 10, 225), (101, 2, 3.5, 100), (51.5, 10, 14, 50), (11, 20, 30, 500), (1001, 1, 1.4, 300)]:
    vo = gain * (v2 - v1) * 1e-3
    add('ia', f'An instrumentation amplifier (gain {gain}) has Vin1 = {v1} mV, Vin2 = {v2} mV and a common-mode voltage of {vcm} mV. What is Vout?', f'Mạch khuếch đại thiết bị (độ lợi {gain}) có Vin1 = {v1} mV, Vin2 = {v2} mV và điện áp chung {vcm} mV. Vout là bao nhiêu?', fmt(vo, 'V'), [fmt(gain * (v2 + v1) * 1e-3, 'V'), fmt(gain * vcm * 1e-3, 'V'), fmt(gain * (v2 - v1) * 1e-3 / 10, 'V'), fmt(-vo, 'V')], f'The common-mode part is rejected: Vout = G(Vin2 − Vin1) = {gain} × {g(v2-v1)} mV = {g(vo)} V.', f'Thành phần chung bị triệt: Vout = G(Vin2 − Vin1) = {gain} × {g(v2-v1)} mV = {g(vo)} V.', S('Floyd Problem 3', 'Floyd Bài 3'), 2)
for a1, a2 in [(30, 10), (20, 5), (50, 4), (100, 3), (8, 12)]:
    add('iso', f'An isolation amplifier has an input-stage gain of {a1} and an output-stage gain of {a2}. What is the total gain?', f'Mạch cách ly có độ lợi tầng vào {a1} và tầng ra {a2}. Độ lợi tổng là bao nhiêu?', g(a1 * a2), [g(a1 + a2), g(a1 / a2), g(a1 * a2 * 2), g(a1 * a2 / 10)], f'Gains of cascaded stages multiply: {a1} × {a2} = {a1*a2}.', f'Độ lợi các tầng nối tiếp nhân với nhau: {a1} × {a2} = {a1*a2}.', S('Floyd Problem 9', 'Floyd Bài 9'))
for vin, io in [(10, 10), (20, 50), (100, 400), (5, 12), (50, 150)]:
    gm = io / vin * 1000
    add('ota', f'An OTA has an input of {vin} mV and an output current of {io} μA. What is gm?', f'OTA có ngõ vào {vin} mV và dòng ra {io} μA. gm bằng bao nhiêu?', fmt(gm, 'μS'), [fmt(vin / io * 1000, 'μS'), fmt(io * vin, 'μS'), fmt(gm / 1000, 'μS'), fmt(gm * 10, 'μS')], f'gm = Iout/Vin = {io} μA/{vin} mV = {g(gm)} μS.', f'gm = Iout/Vin = {io} μA/{vin} mV = {g(gm)} μS.', S('Floyd Problem 14', 'Floyd Bài 14'))
for gm, rl, vin in [(5000, 10, 100), (4000, 6.8, 50), (2000, 22, 20), (8000, 4.7, 10), (1000, 100, 30)]:
    io = gm * 1e-6 * vin * 1e-3; vo = io * rl * 1e3
    add('ota', f'An OTA has gm = {gm} μS, RL = {rl} kΩ and Vin = {vin} mV. What is Vout?', f'OTA có gm = {gm} μS, RL = {rl} kΩ và Vin = {vin} mV. Vout là bao nhiêu?', fmt(vo, 'V'), [fmt(io * 1e6, 'V'), fmt(vo * 1000, 'V'), fmt(vin * 1e-3 * rl, 'V'), fmt(vo / 10, 'V')], f'Iout = gm·Vin = {g(io*1e6)} μA; Vout = Iout·RL = {g(vo)} V (Av = gm·RL = {g(gm*1e-6*rl*1e3)}).', f'Iout = gm·Vin = {g(io*1e6)} μA; Vout = Iout·RL = {g(vo)} V (Av = gm·RL = {g(gm*1e-6*rl*1e3)}).', S('Floyd Problem 15', 'Floyd Bài 15'), 2)
for k, ib in [(16, 100), (16, 50), (16, 200), (20, 75), (16, 25)]:
    gm = k * ib
    add('ota', f'An OTA has K = {k} μS/μA and a bias current of {ib} μA. What is gm?', f'OTA có K = {k} μS/μA và dòng phân cực {ib} μA. gm bằng bao nhiêu?', fmt(gm, 'μS'), [fmt(ib / k, 'μS'), fmt(gm * 10, 'μS'), fmt(k + ib, 'μS'), fmt(gm / 10, 'μS')], f'gm = K·IBIAS = {k} × {ib} = {g(gm)} μS.', f'gm = K·IBIAS = {k} × {ib} = {g(gm)} μS.', S('Floyd Problem 17', 'Floyd Bài 17'), 2)
for vin, r, ir in [(3, 82, 100), (1.5, 47, 60), (2, 100, 50), (5, 100, 80), (1, 10, 100)]:
    vo = -0.025 * math.log(vin / (r * 1e3 * ir * 1e-9))
    add('log', f'A log amplifier (Vout = −0.025 ln(Vin/(R·IR))) has Vin = {vin} V, R = {r} kΩ and IR = {ir} nA. What is Vout?', f'Mạch logarit (Vout = −0,025 ln(Vin/(R·IR))) có Vin = {vin} V, R = {r} kΩ và IR = {ir} nA. Vout là bao nhiêu?', fmt(vo * 1e3, 'mV'), [fmt(-vo * 1e3, 'mV'), fmt(-0.025 * math.log10(vin / (r * 1e3 * ir * 1e-9)) * 1e3, 'mV'), fmt(-0.025 * vin / (r * 1e3 * ir * 1e-9) * 1e3, 'mV'), fmt(vo * 1e3 * 2.3, 'mV')], f'ln({g(vin/(r*1e3*ir*1e-9))}) = {g(math.log(vin/(r*1e3*ir*1e-9)))}; Vout = −0.025 × that = {g(vo*1e3)} mV.', f'ln({g(vin/(r*1e3*ir*1e-9))}) = {g(math.log(vin/(r*1e3*ir*1e-9)))}; Vout = −0,025 × giá trị đó = {g(vo*1e3)} mV.', S('Floyd Problem 27', 'Floyd Bài 27'), 3)
for x in [0.5, 2, 50, 130, 8, 0.1]:
    add('log', f'What is log₁₀ of {x}?', f'log₁₀ của {x} là bao nhiêu?', g(math.log10(x)), [g(math.log(x)), g(10 ** x if x < 5 else x / 10), g(1 / math.log10(x) if x != 1 and math.log10(x) != 0 else 2), g(-math.log10(x))], f'log₁₀({x}) = {g(math.log10(x))}; the natural log would be {g(math.log(x))}.', f'log₁₀({x}) = {g(math.log10(x))}; logarit tự nhiên sẽ là {g(math.log(x))}.', S('Floyd Problem 23', 'Floyd Bài 23'))
C = [('ia','The main advantage of an instrumentation amplifier over a single op-amp difference amplifier is','Ưu điểm chính của mạch khuếch đại thiết bị so với mạch hiệu một op-amp là',('very high input impedance, high CMRR and gain set by one resistor','trở kháng vào rất cao, CMRR cao và độ lợi đặt bằng một điện trở'),[('lower cost','giá thấp hơn'),('fixed gain of one','độ lợi cố định bằng một'),('no need for a power supply','không cần nguồn cấp')],'The input buffers give high Zin and the matched difference stage gives high CMRR.','Các mạch đệm vào cho Zin cao và tầng hiệu cân bằng cho CMRR cao.'),
 ('ia','In an instrumentation amplifier, increasing the gain generally','Ở mạch khuếch đại thiết bị, tăng độ lợi nói chung',('reduces the bandwidth','làm giảm băng thông'),[('increases the bandwidth','làm tăng băng thông'),('increases the CMRR to infinity','làm CMRR tăng tới vô cùng'),('has no effect on anything','không ảnh hưởng gì')],'Gain–bandwidth trade-off (Floyd Fig. 14–6).','Đánh đổi độ lợi–băng thông (Floyd Hình 14–6).'),
 ('iso','An isolation amplifier is chosen mainly for','Mạch khuếch đại cách ly được chọn chủ yếu để',('breaking the ground/electrical path between source and load','ngắt đường nối đất/đường dẫn điện giữa nguồn và tải'),[('increasing the bandwidth','tăng băng thông'),('reducing the supply voltage','giảm điện áp nguồn'),('producing a logarithmic output','tạo ngõ ra logarit')],'Safety and noise immunity come from galvanic isolation.','An toàn và chống nhiễu đến từ cách ly điện.'),
 ('iso','A capacitor-coupled isolation amplifier passes the signal across the barrier by','Mạch cách ly ghép tụ truyền tín hiệu qua rào cách ly bằng cách',('modulating it so the capacitor can couple it','điều chế để tụ có thể ghép tín hiệu'),[('a copper wire','dây đồng'),('a dc current loop','vòng dòng một chiều'),('a resistor divider','bộ chia điện trở')],'A capacitor blocks dc, so the signal is modulated and demodulated across the barrier.','Tụ chặn một chiều nên tín hiệu được điều chế và giải điều chế qua rào cách ly.'),
 ('ota','The gain of an OTA can be varied electronically by changing','Độ lợi của OTA có thể thay đổi bằng điện bằng cách đổi',('the bias current','dòng phân cực'),[('the supply polarity only','chỉ cực tính nguồn'),('the input frequency','tần số vào'),('the package type','kiểu vỏ')],'gm = K·IBIAS, so Av = K·IBIAS·RL.','gm = K·IBIAS nên Av = K·IBIAS·RL.'),
 ('ota','An OTA used with a modulating bias current can act as','OTA dùng với dòng phân cực điều chế có thể làm',('an amplitude modulator','bộ điều biên'),[('a rectifier','bộ chỉnh lưu'),('a clamp','mạch ghim'),('a voltage regulator','bộ ổn áp')],'Varying gm with the modulating signal varies the output amplitude.','Thay đổi gm theo tín hiệu điều chế làm thay đổi biên độ ngõ ra.'),
 ('log','A log amplifier is useful for compressing a signal with','Mạch logarit hữu ích để nén tín hiệu có',('a wide dynamic range','dải động rộng'),[('a narrow dynamic range','dải động hẹp'),('only dc content','chỉ thành phần một chiều'),('no noise','không có nhiễu')],'The logarithm squeezes large ratios into small voltage differences.','Hàm logarit nén tỉ số lớn thành chênh lệch điện áp nhỏ.'),
 ('log','The output of a basic log amplifier is limited to about 0.7 V because','Ngõ ra của mạch logarit cơ bản bị giới hạn khoảng 0,7 V vì',('it is the voltage of a forward-biased pn junction','đó là điện áp của lớp tiếp xúc pn phân cực thuận'),[('the op-amp has low gain','op-amp có độ lợi thấp'),('the supply is only 0.7 V','nguồn chỉ có 0,7 V'),('the input is a sine wave','tín hiệu vào là sóng sin')],'Floyd Problem 25: the pn junction in the feedback path.','Floyd Bài 25: lớp tiếp xúc pn ở nhánh hồi tiếp.'),
 ('log','Cascading a log amplifier and an antilog amplifier can implement','Ghép tầng mạch logarit và mạch đối logarit có thể thực hiện',('multiplication or division of signals','phép nhân hoặc chia tín hiệu'),[('rectification','chỉnh lưu'),('level shifting only','chỉ dịch mức'),('filtering','lọc')],'ln(a) + ln(b) = ln(ab): add logs, then take the antilog.','ln(a) + ln(b) = ln(ab): cộng logarit rồi lấy đối logarit.'),
 ('ia','Which input signal is rejected most by an ideal instrumentation amplifier?','Tín hiệu vào nào bị mạch khuếch đại thiết bị lý tưởng triệt nhiều nhất?',('a signal common to both inputs','tín hiệu chung ở cả hai ngõ vào'),[('a signal between the two inputs','tín hiệu giữa hai ngõ vào'),('a dc difference voltage','điện áp hiệu một chiều'),('a low-frequency difference signal','tín hiệu hiệu tần số thấp')],'Only the difference Vin2 − Vin1 is amplified.','Chỉ hiệu Vin2 − Vin1 được khuếch đại.')]
for tp, qe, qv, ca, ws, xe, xv in C: G.concept(tp, qe, qv, ca, ws, xe, xv)
F = 'assets/figs/m05/'
G.ca('ia', 'If RG in Figure 14–7 is decreased, the voltage gain will', 'Nếu giảm RG trong Hình 14–7 thì độ lợi điện áp sẽ', F + 'fig14_6_7.png', 0, 'G = 1 + 50.5 kΩ/RG rises as RG falls.', 'G = 1 + 50,5 kΩ/RG tăng khi RG giảm.', ('Floyd CA Q1', 'Floyd CA câu 1'))
G.ca('iso', 'If Ri1 in the isolation amplifier of Figure 14–15 is increased to 4.7 kΩ, the total voltage gain will', 'Nếu tăng Ri1 của mạch cách ly ở Hình 14–15 lên 4,7 kΩ thì độ lợi tổng sẽ', F + 'fig14_15.png', 1, 'Input-stage gain Rf1/Ri1 falls from 22/2.2 = 10 to 22/4.7 ≈ 4.7.', 'Độ lợi tầng vào Rf1/Ri1 giảm từ 22/2,2 = 10 xuống 22/4,7 ≈ 4,7.', ('Floyd CA Q4', 'Floyd CA câu 4'))
G.ca('iso', 'If Rf2 in the output stage of Figure 14–15 is increased, the total voltage gain will', 'Nếu tăng Rf2 ở tầng ra của Hình 14–15 thì độ lợi tổng sẽ', F + 'fig14_15.png', 0, 'The output-stage gain grows with Rf2, and the total gain is the product of the stages.', 'Độ lợi tầng ra tăng theo Rf2 và độ lợi tổng là tích các tầng.', ('Floyd CA Q4', 'Floyd CA câu 4'))
G.ca('ota', 'If RL in the OTA of Figure 14–23 is increased, the voltage gain will', 'Nếu tăng RL của OTA ở Hình 14–23 thì độ lợi điện áp sẽ', F + 'fig14_23.png', 0, 'Av = gm·RL.', 'Av = gm·RL.', ('Floyd CA Q6', 'Floyd CA câu 6'))
G.ca('ota', 'If the bias current in the OTA of Figure 14–23 is reduced, the voltage gain will', 'Nếu giảm dòng phân cực của OTA ở Hình 14–23 thì độ lợi điện áp sẽ', F + 'fig14_23.png', 1, 'gm = K·IBIAS falls, so Av falls.', 'gm = K·IBIAS giảm nên Av giảm.', ('Floyd CA Q7', 'Floyd CA câu 7'))
G.ca('log', 'In the log amplifier of Figure 14–31, the magnitude of the output voltage |VOUT| is about 0.7 V (one diode drop). If R1 is decreased to a smaller value, |VOUT| will', 'Ở mạch logarit Hình 14–31, độ lớn điện áp ra |VOUT| khoảng 0,7 V (một sụt áp điốt). Nếu giảm R1 xuống giá trị nhỏ hơn thì |VOUT| sẽ', F + 'fig14_31.png', 0, 'The diode current grows (I = Vin/R1) and VD grows with its logarithm: |VOUT| rises slightly.', 'Dòng điốt tăng (I = Vin/R1) và VD tăng theo logarit của nó: |VOUT| tăng nhẹ.', ('Floyd CA Q8', 'Floyd CA câu 8'))
G.write()
